if (!items || items.length === 0) return;

const payload = items
    .map(w => ({
        PositionId: positionId,
        WorkerId: w.WorkerId,
        CustomAnnualRate: w.CustomAnnualRate || null
    }))
    .filter(p => p.PositionId && p.WorkerId);

if (payload.length === 0) {
    console.warn("Batch insert skipped: No valid WorkerIds found in items.", items);
    return;
}

await apiService.send(`${this.BATCH_ENDPOINT}/insert`, "POST", payload, false);

if (!items || items.length === 0) return;

const payload = items;

return apiService.send(`${this.BATCH_ENDPOINT}/update`, "PUT", payload, false);

if (!items || items.length === 0) return;

const payload = items
    .filter(w => w.Id)
    .map(w => ({ Id: w.Id }));

if (payload.length === 0) return;

await apiService.send(`${this.BATCH_ENDPOINT}/delete`, "POST", payload, false);

if (!positionId) throw new Error("Target Position ID is missing");

const originalMap = new Map(originalItems.map(w => [w.WorkerId, w]));
const originalSet = new Set(originalItems.map(w => w.WorkerId));
const finalSet = new Set(finalItems.map(w => w.WorkerId));

const toInsert = finalItems.filter(w => !originalSet.has(w.WorkerId));
const toDelete = originalItems
    .filter(w => !finalSet.has(w.WorkerId))
    .map(w => ({
        Id: w._linkId
    }));

const toUpdate = [];
finalItems.forEach(newItem => {
    const oldItem = originalMap.get(newItem.WorkerId);

    if (oldItem) {
        const hasChanged = newItem.CustomAnnualRate != oldItem.CustomAnnualRate;

        if (hasChanged) {
            toUpdate.push({
                Id: oldItem._linkId,
                CustomAnnualRate: newItem.CustomAnnualRate || null
            });
        }
    }
});

const promises = [];
if (toInsert.length > 0) promises.push(this._batchInsert(apiService, toInsert, positionId));
if (toUpdate.length > 0) promises.push(this._batchUpdate(apiService, toUpdate));
if (toDelete.length > 0) promises.push(this._batchDelete(apiService, toDelete));

await Promise.all(promises);
return true;
